library(shiny)
library(jsonlite)

source("R/ingest.R")
source("R/decode.R")
source("R/templates.R")

DICTS <- load_dictionaries("data/var_key.csv", "data/value_labels.csv")

# The bridge loads its ~30 MB of wasm and fonts from "../vendor/". Under
# shinylive the app runs in an iframe at /app_<random>/, so that resolves to
# the SITE root, where the static host serves vendor/ - deliberately outside
# the app bundle so it never enters webR's virtual filesystem.
#
# Desktop shiny::runApp has no such iframe: the page is at "/", the same
# request lands on Shiny itself, and vendor/ 404s - so Generate fails with
# "Failed to fetch dynamically imported module". Registering the directory
# here makes runApp behave like the deployed layout.
#
# The dir.exists() guard is what keeps this safe in production: vendor/ is
# not copied into the shinylive bundle, so the branch is simply skipped
# there. Calling addResourcePath() on a missing directory would error and
# stop the app from starting.
if (dir.exists("vendor")) addResourcePath("vendor", "vendor")

ui <- fluidPage(
  tags$head(
    tags$script(src = "typst-bridge.js", type = "module"),
    tags$style(HTML("
      body { max-width: 46rem; margin: 0 auto; padding: 2rem 1.25rem 4rem;
             font-family: system-ui, sans-serif; color: #1a1a1a; }
      h1 { font-size: 1.4rem; margin-bottom: .25rem; }
      .lede { color: #4d4d4d; margin-bottom: 1.75rem; line-height: 1.5; }
      .panel { border: 1px solid #d8d8d8; border-radius: 6px;
               padding: 1.1rem 1.25rem; margin-bottom: 1.1rem; }
      .problem { border-left: 3px solid #b3261e; background: #fdf5f4; }
      .ready { border-left: 3px solid #1f4e5f; background: #f4f8f9; }
      #status { font-variant-numeric: tabular-nums; color: #4d4d4d; }
    "))
  ),
  h1("Report Generator"),
  p(class = "lede",
    "Export your dashboard as a CSV file; drop it below to get an advising report for each student. Your data stays in this browser tab and is never uploaded."),

  div(class = "panel",
      fileInput("file", "Choose your dashboard export", accept = ".csv",
                width = "100%", buttonLabel = "Browse", placeholder = "No file chosen")),

  div(class = "panel",
      radioButtons("rtype", "Report type",
                   choices = setNames(names(TEMPLATES),
                                      vapply(TEMPLATES, `[[`, "", "label")),
                   selected = names(TEMPLATES)[1])),

  uiOutput("check"),

  div(class = "panel",
      actionButton("go", "Generate reports", class = "btn-primary"),
      tags$p(id = "status", style = "margin-top:.85rem;"))
)

server <- function(input, output, session) {

  upload <- reactive({
    req(input$file)
    read_upload(input$file$datapath)
  })

  filtered <- reactive({
    u <- upload()
    if (!u$ok) return(NULL)
    filter_by_type(u$data, input$rtype)
  })

  output$check <- renderUI({
    u <- upload()
    if (!u$ok) return(div(class = "panel problem", strong("Problem: "), u$error))

    bad <- validate_template_fields(TEMPLATES[[input$rtype]]$fields, DICTS)
    if (length(bad) > 0) {
      return(div(class = "panel problem", strong("Template error: "),
                 sprintf("unknown variable(s) %s", paste(bad, collapse = ", "))))
    }

    f <- filtered()
    cls <- if (f$n_kept == 0) "panel problem" else "panel ready"
    div(class = cls, tally_message(f, input$rtype))
  })

  observeEvent(input$go, {
    u <- upload()
    if (!u$ok) return(showNotification(u$error, type = "error", duration = NULL))

    f <- filtered()
    if (f$n_kept == 0) {
      return(showNotification(tally_message(f, input$rtype),
                              type = "error", duration = NULL))
    }

    tpl <- TEMPLATES[[input$rtype]]
    msg <- build_compile_message(f$kept, tpl, DICTS, filename_mode = "name")

    session$sendCustomMessage("compile_typst", msg)
  })

  observeEvent(input$compile_result, {
    res <- input$compile_result
    if (isTRUE(res$ok)) {
      msg <- sprintf("Generated %d report(s).", res$n)
      if (res$failed > 0) msg <- paste(msg, sprintf("%d failed; see errors.txt in the zip.", res$failed))
      showNotification(msg, type = "message")
    } else {
      showNotification(paste("Generation failed:", res$error), duration = NULL, type = "error")
    }
  })
}

shinyApp(ui, server)

# Loads the two dictionaries. var_key.csv is canonical for which variables
# exist; value_labels.csv maps coded values to display text.
load_dictionaries <- function(var_key_path, value_labels_path) {
  vk <- read.csv(var_key_path, stringsAsFactors = FALSE, check.names = FALSE,
                 colClasses = "character", na.strings = character(0))
  vl <- read.csv(value_labels_path, stringsAsFactors = FALSE, check.names = FALSE,
                 colClasses = "character", na.strings = character(0))
  vl$key <- paste(vl$var, vl$value, sep = "\r")
  list(var_key = vk, value_labels = vl)
}

# Returns the names of fields not present in var_key.csv. An empty result
# means every field is known. This is what catches hapc13 vs hapcl13 at
# load time instead of as a silently blank cell.
validate_template_fields <- function(field_names, dicts) {
  setdiff(field_names, dicts$var_key$vars)
}

# Decodes one row into display-ready strings. Missing, NA, and unmatched
# codes all become "" so Typst renders a blank rather than the text "NA".
decode_row <- function(row, dicts) {
  vl <- dicts$value_labels
  out <- lapply(names(row), function(nm) {
    raw <- row[[nm]]
    if (is.null(raw) || length(raw) == 0 || is.na(raw)) return("")
    raw <- as.character(raw)
    if (!nzchar(raw)) return("")

    hit <- vl$label[match(paste(nm, raw, sep = "\r"), vl$key)]
    if (length(hit) == 1 && !is.na(hit)) {
      # A variable present in value_labels but with a blank label for this
      # code means "show nothing", not "show the code".
      return(hit)
    }
    # Variable has coded labels but this code is not among them -> blank.
    if (nm %in% vl$var) return("")
    raw
  })
  names(out) <- names(row)
  out
}

REQUIRED_COLS <- c("Stype", "FN17", "LN17", "bstudidC2")

# Reads an uploaded dashboard export.
# Everything is read as character on purpose: student IDs carry leading
# zeros and survey codes are mixed-type. Coercing would corrupt both.
read_upload <- function(path) {
  if (!file.exists(path)) {
    return(list(ok = FALSE, data = NULL, error = "The file could not be read."))
  }

  df <- tryCatch(
    read.csv(path, stringsAsFactors = FALSE, check.names = FALSE,
             colClasses = "character", na.strings = character(0)),
    error = function(e) NULL
  )

  if (is.null(df) || ncol(df) == 0) {
    return(list(ok = FALSE, data = NULL,
                error = "The file could not be read as CSV."))
  }

  missing <- setdiff(REQUIRED_COLS, names(df))
  if (length(missing) > 0) {
    return(list(ok = FALSE, data = NULL, error = sprintf(
      "This file is missing required column(s): %s.",
      paste(missing, collapse = ", ")
    )))
  }

  list(ok = TRUE, data = df, error = NULL)
}

// ===============================================
// Shared styles and helpers for BCSSE Advising reports
// ===============================================

#let accent = rgb("#1f4e5f")   // 9.08:1 on white - AA and AAA
#let muted  = rgb("#4d4d4d")   // label grey - AA on white

// `report` is applied by each report file via `#show: report.with(...)`.
// The document title is not decoration: PDF/UA-1 requires it, and screen
// readers announce it. `lang` drives pronunciation and hyphenation.
#let report(title: "BCSSE Advising Report", body) = {
  set document(title: title, author: "BCSSE")
  set text(lang: "en")
  set page(paper: "us-letter", margin: (x: 2.2cm, y: 2cm))
  set text(font: ("Libertinus Serif", "New Computer Modern"), size: 10.5pt)
  show heading: set text(font: ("Libertinus Serif", "New Computer Modern"))

  // A real level-1 heading, so the tag tree gets /H1 rather than a styled
  // text run that a screen reader cannot navigate to.
  heading(level: 1, title)
  body
}

// A missing key renders blank instead of halting the compile.
#let field(row, key) = {
  let v = row.at(key, default: "")
  if v == none { "" } else { str(v) }
}

// `table.header` is what produces /THead and /TH in the tag tree. Without
// it the cells tag as plain /TD and a screen reader loses the association
// between label and response.
#let item-table(row, items) = {
  table(
    columns: (1fr, 1fr),
    stroke: none,
    inset: (x: 0pt, y: 4pt),
    table.header([*Item*], [*Response*]),
    ..items.map(it => (
      text(fill: muted, it.at(1)),
      field(row, it.at(0)),
    )).flatten()
  )
}

#let section(title, row: (:), items: (), prompt: none) = {
  block(breakable: false, {
    heading(level: 2, text(fill: accent, title))
    if prompt != none {
      v(-4pt)
      text(size: 10.5pt, prompt)
      linebreak()
    }
    v(6pt)
  })
  item-table(row, items)
  v(16pt)
}

// Bridges Shiny (running in webR) to typst.ts. All compilation happens in
// this tab; nothing here performs network I/O after initial asset load.
//
// Vendor assets live at the SITE root, not inside the app bundle. The app
// runs in an iframe at a per-load random /app_<id>/ path, so "./vendor/"
// resolves into the app scope and 404s. "../vendor/" reaches the site root
// and also survives deployment under a subpath.
const VENDOR = '../vendor/';

let typstPromise = null;
async function getTypst() {
  if (!typstPromise) {
    typstPromise = (async () => {
      const { $typst, TypstSnippet } = await import(VENDOR + 'typst-snippet.mjs');
      $typst.setCompilerInitOptions({
        getModule: () => VENDOR + 'typst_ts_web_compiler_bg.wasm',
      });
      // typst.ts defaults to cdn.jsdelivr.net for fonts. Overriding this is
      // what keeps the page free of third-party requests and lets a
      // connect-src 'none' CSP hold.
      $typst.use(TypstSnippet.preloadFontAssets({
        assets: ['text'],
        assetUrlPrefix: { text: VENDOR + 'fonts/' },
      }));
      return $typst;
    })();
  }
  return typstPromise;
}

const status = (msg) => {
  const el = document.getElementById('status');
  if (el) el.textContent = msg;
};

const saveBlob = (blob, filename) => {
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
};

const send = (name, payload) => Shiny.setInputValue(name, payload, { priority: 'event' });
const breathe = () => new Promise((r) => setTimeout(r, 0));

// Guards against a second Generate click racing the first. Two loops sharing
// one compiler would interleave writes to /data.json and emit PDFs holding
// the wrong students' data - silent, and a confidentiality breach.
let running = false;

Shiny.addCustomMessageHandler('compile_typst', async (msg) => {
  if (running) return;
  running = true;
  try {
    status('Starting Typst...');
    const $typst = await getTypst();

    await $typst.addSource('/typst/BCSSE_template.typ', msg.sharedTemplate);
    await $typst.addSource('/typst/main.typ', msg.mainTemplate);

    const rows = JSON.parse(msg.rows);
    const names = msg.filenames;

    const JSZip = (await import(VENDOR + 'jszip.min.js')).default || window.JSZip;
    const zip = new JSZip();
    const failures = [];

    for (let i = 0; i < rows.length; i++) {
      try {
        await $typst.addSource('/data.json', JSON.stringify(rows[i]));
        const pdf = await $typst.pdf({ mainFilePath: '/typst/main.typ' });
        zip.file(names[i] || `report-${i + 1}.pdf`, pdf);
      } catch (e) {
        // A first-row failure is nearly always the template; a later one is
        // nearly always the data. Abort on the former so one syntax error
        // does not produce N copies of the same message.
        if (i === 0) throw new Error(`Template failed to compile: ${e}`);
        failures.push(`row ${i + 1} (id ${rows[i].bstudidC2 ?? 'unknown'}): ${e}`);
      }
      if (i % 10 === 0) {
        status(`Compiling ${i + 1} of ${rows.length}...`);
        send('compile_progress', { done: i + 1, total: rows.length });
        await breathe();
      }
    }

    if (failures.length) zip.file('errors.txt', failures.join('\n'));

    status('Building zip...');
    const blob = await zip.generateAsync({ type: 'blob' });
    saveBlob(blob, msg.zipName || 'advising-reports.zip');

    const n = rows.length - failures.length;
    status(`Done - ${n} of ${rows.length} files.`);
    send('compile_result', { ok: true, n, failed: failures.length, error: null });
  } catch (e) {
    status('Generation failed.');
    send('compile_result', { ok: false, n: 0, failed: 0, error: String(e) });
  } finally {
    running = false;
  }
});
